import{_ as t}from"./chunks/architecture.DdIdPF_l.js";import{_ as a,o as i,c as s,a6 as r}from"./chunks/framework.CKIbuWFA.js";const k=JSON.parse('{"title":"Architecture de l’application et des services","description":"","frontmatter":{"title":"Architecture de l’application et des services","docId":"developer.architecture","translationKey":"developer.architecture","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"c1d4d9160416178f0dc2412de9b2c62dec536ceedcca7cef41297fc3a2809b81","order":30},"headers":[],"relativePath":"fr/developer/architecture.md","filePath":"fr/developer/architecture.md","lastUpdated":1794611623000}'),o={name:"fr/developer/architecture.md"};function n(c,e,l,d,p,u){return i(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="application-and-service-architecture" tabindex="-1">Architecture de l’application et des services <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;Architecture de l’application et des services {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Placer une modification dans le service propriétaire de son état. Lisez la <a href="./setup.html">configuration</a> et comprenez la différence entre un hôte existant et un hôte autonome explicite. Le bureau construit un <code>AppCore</code>, l’enveloppe dans un <code>ControlApi</code> et expose cette instance à la WebView, à la CLI locale et aux agents.</p><h2 id="trace-an-operation" tabindex="-1">Suivre une opération <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;Suivre une opération {#trace-an-operation}&quot;">​</a></h2><ol><li>Trouvez l’enregistrement de la méthode dans <code>crates/tiktools-control-api/src/modules/</code>. Il fournit les schémas, la politique et les métadonnées de découverte.</li><li>Suivez le gestionnaire dans <code>crates/tiktools-core/src/control/</code> et le service propriétaire. Placez ici la validation métier et les mutations persistantes plutôt que dans un adaptateur de transport.</li><li>Ajoutez l’enveloppe typée dans <code>crates/tiktools-client</code> ; son test de parité compare la couverture du SDK à la surface enregistrée.</li><li>Consommez la méthode via <code>src/web/shared/api/control-client.ts</code>. Les entités Vue conservent l’état de présentation ; le bureau ne transmet à la WebView ni base de données ni objet d’intégration native.</li></ol><p>Winit possède la boucle d’événements, Wry la WebView et l’intégration de zone de notification son icône. <code>HostEmitter</code> et les événements métier transportent des valeurs sérialisées hors du cœur. Le bureau transmet le travail via le proxy de sa boucle d’événements ; l’évaluation de scripts WebView reste sur ce thread. Tokio exécute les opérations asynchrones de l’hôte.</p><h2 id="concrete-boundary-check" tabindex="-1">Vérification concrète des frontières <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;Vérification concrète des frontières {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>La première commande vérifie le client de l’interface. La seconde exécute directement la cible d’intégration du SDK en préservant le fichier de verrouillage ; les options de cible Cargo passent par <code>rust</code> plutôt que par la grammaire plus restreinte des tests ciblés.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Tous les clients observent le même parcours faisant autorité pour les opérations et événements. <code>host --ipc</code>, <code>host --stdio</code> et <code>--standalone</code> créent intentionnellement un propriétaire sans interface graphique ; les commandes CLI normales se rattachent à un propriétaire actif. L’ancien parcours <code>PageMessage</code>/<code>IpcRouter</code> reste du code de compatibilité et ne doit pas recevoir de nouvelles variantes de messages.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Si deux clients divergent, comparez l’identité de l’hôte, le répertoire d’application, les fonctionnalités de compilation et la découverte avant d’ajouter un autre store. Un plugin absent est un problème de catalogue d’exécution, pas une raison de compiler son implémentation dans le cœur. Les documents d’architecture historiques contiennent des chemins d’interface retirés ; suivez le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">cœur actuel</a> et le <a href="./frontend.html">plan de l’interface</a> lorsqu’ils diffèrent.</p><p><img src="`+t+'" alt="AppCore TikTools, transport, ControlClient et espace de travail Vue réel"></p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Les features Cargo du binaire choisi déterminent les chemins compilés. Le cœur active par défaut <code>native-plugins</code> et <code>napi-vm-node-api</code> ; <code>persistence</code> fournit SQLite, <code>native-tiktok</code> l’adaptateur/entrée LIVE, et <code>plugin-install</code>, <code>cloud-auth</code>, <code>app-update</code> leurs services. Consultez <code>cargo tree -p tiktools-desktop -e features</code> (ou la CLI choisie), puis <code>system.info</code>/discovery. La compilation ne prouve pas la disponibilité configurée. Testez l’entrée LIVE avec la régression <code>native-tiktok</code> de <a href="./performance.html">performance</a>.</p>',16)])])}const v=a(o,[["render",n]]);export{k as __pageData,v as default};
